use std::path::Path;
use std::fs;

/// Main build script entry point.
/// Loads environment variables and tenant configuration, then generates build artifacts.
fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Load .env file generated by bundle-tenant.py (if present)
    // Falls back gracefully when building without the bundler
    let _ = dotenvy::from_path(Path::new("src-tauri/.env"));

    // Track tenant config changes for rebuild triggers
    let tenant_config_path = std::env::var("TENANT_CONFIG")
        .unwrap_or_else(|_| "tenant-configs/default.json".to_string());

    let config_path = Path::new(&tenant_config_path);
    if config_path.exists() {
        println!("cargo:rerun-if-changed={}", config_path.display());

        // Read and copy tenant config to OUT_DIR for runtime inclusion
        let out_dir = std::env::var("OUT_DIR")?;
        let dest_path = Path::new(&out_dir).join("tenant-config.json");
        fs::copy(config_path, &dest_path)
            .map_err(|e| format!("Failed to copy tenant config to OUT_DIR: {}", e))?;

        // Parse and validate JSON
        let config_str = fs::read_to_string(config_path)
            .map_err(|e| format!("Failed to read tenant config: {}", e))?;
        let _config: serde_json::Value = serde_json::from_str(&config_str)
            .map_err(|e| format!("Tenant config is not valid JSON: {}", e))?;

        // Emit env var for runtime access to the config file path
        println!("cargo:rustc-env=TENANT_CONFIG_PATH={}", dest_path.display());

        // Generate Rust module with embedded config for compile-time inclusion
        generate_tenant_config_module(&config_str, &Path::new(&out_dir))?;

        // Template tauri.conf.json with tenant-specific values
        let tenant_id = std::env::var("TENANT_ID")
            .unwrap_or_else(|_| "default".to_string());
        let commercial_name = std::env::var("COMMERCIAL_NAME")
            .unwrap_or_else(|_| "MindLdger".to_string());
        template_tauri_conf(&tenant_id, &commercial_name)?;
    }

    // Build Tauri application
    tauri_build::build();

    Ok(())
}

/// Templates tauri.conf.json with tenant-specific values.
/// Reads the existing config, updates identifier, productName, and window title,
/// then writes the modified config back for tauri-build to consume.
fn template_tauri_conf(tenant_id: &str, commercial_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let tauri_conf_path = Path::new("src-tauri/tauri.conf.json");
    let content = fs::read_to_string(tauri_conf_path)
        .map_err(|e| format!("Failed to read tauri.conf.json: {}", e))?;

    let mut conf: serde_json::Value = serde_json::from_str(&content)
        .map_err(|e| format!("Invalid tauri.conf.json: {}", e))?;

    conf["identifier"] = serde_json::Value::String(format!("com.mindledger.{}.desktop", tenant_id));
    conf["productName"] = serde_json::Value::String(commercial_name.to_string());
    if let Some(windows) = conf["app"]["windows"].as_array_mut() {
        if let Some(first_window) = windows.first_mut() {
            first_window["title"] = serde_json::Value::String(commercial_name.to_string());
        }
    }

    let new_content = serde_json::to_string_pretty(&conf)
        .map_err(|e| format!("Failed to serialize tauri.conf.json: {}", e))?;

    fs::write(tauri_conf_path, new_content)
        .map_err(|e| format!("Failed to write templated tauri.conf.json: {}", e))?;

    Ok(())
}

/// Generates a Rust module with embedded tenant config for compile-time inclusion.
/// Writes the generated module to OUT_DIR and emits the path via cargo:rustc-env.
fn generate_tenant_config_module(config_str: &str, out_dir: &Path) -> Result<(), Box<dyn std::error::Error>> {
    // Serialize the config string as a JSON string literal for embedding
    let json_str = serde_json::to_string(config_str)
        .map_err(|e| format!("Failed to serialize config as string literal: {}", e))?;

    let module_content = format!(
        r#"// Auto-generated by build.rs - DO NOT EDIT
/// Embedded tenant configuration JSON
pub const TENANT_CONFIG_JSON: &str = {json_str};
"#
    );

    let module_path = out_dir.join("tenant_config.rs");
    fs::write(&module_path, module_content)
        .map_err(|e| format!("Failed to write tenant_config.rs: {}", e))?;

    println!("cargo:rustc-env=TENANT_CONFIG_RS_PATH={}", module_path.display());
    Ok(())
}
